import React, { Component } from 'react';
import './index.css';

class Spaceship extends Component {
  constructor(props) {
    super(props);
    this.el = null;
    this.timer = null;
  }

  shouldComponentUpdate() {
    return false;
  }

  componentDidMount() {
    this.schedule();
  }

  componentWillUnmount() {
    if (this.timer != null) {
      clearTimeout(this.timer);
    }
  }

  setRef = (el) => {
    this.el = el;
  };

  schedule = () => {
    // Random gap between flybys (~12–45s)
    const delay = 12000 + Math.random() * 33000;
    this.timer = setTimeout(this.flyby, delay);
  };

  flyby = () => {
    const el = this.el;
    if (!el) {
      this.schedule();
      return;
    }

    el.classList.remove('Spaceship--flying');
    el.classList.remove('Spaceship--reverse');
    void el.offsetWidth;

    const top = 8 + Math.random() * 32;
    const duration = 4.5 + Math.random() * 3.5;
    const reverse = Math.random() > 0.5;
    const scale = 0.7 + Math.random() * 0.55;

    el.style.top = top + '%';
    el.style.animationDuration = duration + 's';
    el.style.setProperty('--ship-scale', String(scale));
    if (reverse) {
      el.classList.add('Spaceship--reverse');
    }
    el.classList.add('Spaceship--flying');

    this.timer = setTimeout(this.schedule, duration * 1000 + 400);
  };

  render() {
    return (
      <div className="Spaceship" ref={this.setRef} aria-hidden="true">
        <svg className="Spaceship__svg" viewBox="0 0 120 48" overflow="visible">
          <ellipse className="Spaceship__trail" cx="18" cy="24" rx="14" ry="4" />
          {/* silhouette hull */}
          <ellipse className="Spaceship__body" cx="62" cy="26" rx="42" ry="10" />
          <ellipse className="Spaceship__body" cx="62" cy="22" rx="28" ry="8" />
          <ellipse className="Spaceship__dome" cx="62" cy="16" rx="14" ry="10" />
          {/* porthole lights — only detail that pops at night */}
          <circle className="Spaceship__light Spaceship__light--a" cx="40" cy="26" r="2.4" />
          <circle className="Spaceship__light Spaceship__light--b" cx="62" cy="28" r="2.4" />
          <circle className="Spaceship__light Spaceship__light--c" cx="84" cy="26" r="2.4" />
        </svg>
      </div>
    );
  }
}

export default Spaceship;
