import React, { Component } from 'react';
import './index.css';

function makeStars(count) {
  const stars = [];
  for (let i = 0; i < count; i++) {
    stars.push({
      id: i,
      left: Math.random() * 100,
      top: Math.random() * 70,
      size: 1 + Math.random() * 2,
      twinkle: i % 3 === 0,
      delay: Math.random() * 4,
      duration: 2 + Math.random() * 2.5,
    });
  }
  return stars;
}

class Sky extends Component {
  constructor(props) {
    super(props);
    this.stars = makeStars(36);
  }

  shouldComponentUpdate() {
    return false;
  }

  render() {
    return (
      <div className="Sky">
        <div className="Sky__stars">
          {this.stars.map((star) => (
            <span
              key={star.id}
              className={star.twinkle ? 'Sky__star Sky__star--twinkle' : 'Sky__star'}
              style={{
                left: star.left + '%',
                top: star.top + '%',
                width: star.size,
                height: star.size,
                animationDelay: star.delay + 's',
                animationDuration: star.duration + 's',
              }}
            />
          ))}
        </div>

        {/* Evening/morning star — brighter & warmer than the rest */}
        <div className="Sky__venus" title="Venus" />

        <div className="Sky__sun">
          <svg viewBox="0 0 100 100" className="Sky__celestial-svg">
            <defs>
              <radialGradient id="sunGlow" cx="50%" cy="50%" r="50%">
                <stop offset="0%" stopColor="#FFF8C0" stopOpacity="1" />
                <stop offset="40%" stopColor="#FFD040" stopOpacity="0.95" />
                <stop offset="70%" stopColor="#FF9020" stopOpacity="0.35" />
                <stop offset="100%" stopColor="#FF6020" stopOpacity="0" />
              </radialGradient>
            </defs>
            <circle cx="50" cy="50" r="48" fill="url(#sunGlow)" />
            <circle cx="50" cy="50" r="18" fill="#FFF4A0" />
          </svg>
        </div>

        <div className="Sky__moon">
          <svg viewBox="0 0 100 100" className="Sky__celestial-svg">
            <defs>
              <radialGradient id="moonGlow" cx="50%" cy="50%" r="50%">
                <stop offset="0%" stopColor="#E8F0FF" stopOpacity="0.9" />
                <stop offset="55%" stopColor="#C0D0F0" stopOpacity="0.25" />
                <stop offset="100%" stopColor="#A0B0E0" stopOpacity="0" />
              </radialGradient>
            </defs>
            <circle cx="50" cy="50" r="48" fill="url(#moonGlow)" />
            <circle cx="50" cy="50" r="16" fill="#E8EEF8" />
            <circle cx="44" cy="46" r="3" fill="#C8D0E0" opacity="0.55" />
            <circle cx="56" cy="52" r="2.2" fill="#C8D0E0" opacity="0.45" />
          </svg>
        </div>
      </div>
    );
  }
}

export default Sky;
