import React, { Component } from 'react';
import './index.css';

function makeClouds(count) {
  const clouds = [];
  for (let i = 0; i < count; i++) {
    const scale = 0.55 + Math.random() * 0.85;
    clouds.push({
      id: i,
      top: 8 + Math.random() * 32,
      scale,
      duration: 60 + Math.random() * 50,
      delay: -Math.random() * 60,
      opacity: 0.35 + Math.random() * 0.4,
      blobs: [
        { cx: 40, cy: 50, rx: 28, ry: 18 },
        { cx: 62, cy: 46, rx: 22, ry: 16 },
        { cx: 78, cy: 52, rx: 18, ry: 12 },
        { cx: 52, cy: 38, rx: 16, ry: 12 },
      ],
    });
  }
  return clouds;
}

class Clouds extends Component {
  constructor(props) {
    super(props);
    this.clouds = makeClouds(4);
  }

  shouldComponentUpdate() {
    return false;
  }

  render() {
    return (
      <div className="Clouds">
        {this.clouds.map((cloud) => (
          <div
            key={cloud.id}
            className="Clouds__cloud"
            style={{
              top: cloud.top + '%',
              opacity: cloud.opacity,
              animationDuration: cloud.duration + 's',
              animationDelay: cloud.delay + 's',
              transform: `scale(${cloud.scale})`,
            }}
          >
            <svg viewBox="0 0 120 70" className="Clouds__svg">
              {cloud.blobs.map((b, i) => (
                <ellipse
                  key={i}
                  className="Clouds__blob"
                  cx={b.cx}
                  cy={b.cy}
                  rx={b.rx}
                  ry={b.ry}
                />
              ))}
            </svg>
          </div>
        ))}
      </div>
    );
  }
}

export default Clouds;
