import React, { Component } from 'react';
import PropTypes from 'prop-types';
import Mountain from './Mountain';
import {getRandomArbitrary} from "./utils";
import './MountainRange.css';

class MountainRange extends Component {
  static propTypes = {
    numberOfMountains: PropTypes.number.isRequired,
    rangeId: PropTypes.string
  }

  static defaultProps = {
    numberOfMountains: 10,
    rangeId: 'r'
  }

	constructor(props) {
		super(props);

    this.mountains = new Array(this.props.numberOfMountains);
    for(let i = 0; i < this.props.numberOfMountains; i++) {
      let width = getRandomArbitrary(30, 100);

      this.mountains[i] = {
        x: getRandomArbitrary(0, 100-width),
        width: width
      };
    }

    this.mountains = this.mountains.sort(function(a,b) {return (a.width > b.width) ? 1 : ((b.width > a.width) ? -1 : 0);} );
    for(let i = 0; i < this.props.numberOfMountains; i++) {
      this.mountains[i] = {
        ...this.mountains[i],
        depth: i
      };
    };
	}

  shouldComponentUpdate() {
    return false;
  }

  render() {
    let mountainRangeStyle = {
      width: "100%",
      height: "80%",
      position: "absolute",
      top: "20%",
      left: 0
    }

    let mountains = this.mountains.map((mountain, index) => {
        let width = mountain.width;
        let height = mountain.width;

        let mountainStyle = {
          position: "absolute",
          bottom: 0,
          left: mountain.x + "%",
          backgroundColor: "transparent",
          transform: "scale(" + (mountain.depth + 1) / this.props.numberOfMountains + ")",
          transformOrigin: "bottom right",
          zIndex: mountain.depth,
          overflowY: "hidden"
        }

        return (
          <Mountain
            key={index}
            rangeId={this.props.rangeId}
            index={index}
            style={mountainStyle}
            width={width}
            height={height}
            levels={4 + parseInt(((mountain.depth  + 1)/ this.props.numberOfMountains) * 2, 10)}
            z={(mountain.depth + 1) / this.props.numberOfMountains}
          />
        );
    });

    return (
      <div className="MountainRange" style={mountainRangeStyle}>
        {mountains}
      </div>
    );
  }
}

export default MountainRange;
