import React, { Component } from 'react';
import './index.css';

function makeBirds(count) {
  const birds = [];
  for (let i = 0; i < count; i++) {
    birds.push({
      id: i,
      top: 12 + Math.random() * 28,
      size: 18 + Math.random() * 14,
      duration: 20 + Math.random() * 16,
      delay: -Math.random() * 20,
      flapDuration: 0.4 + Math.random() * 0.25,
      flapDelay: Math.random() * 0.4,
    });
  }
  return birds;
}

class Birds extends Component {
  constructor(props) {
    super(props);
    this.birds = makeBirds(4);
  }

  shouldComponentUpdate() {
    return false;
  }

  render() {
    return (
      <div className="Birds">
        {this.birds.map((bird) => (
          <div
            key={bird.id}
            className="Birds__bird"
            style={{
              top: bird.top + '%',
              width: bird.size,
              height: bird.size * 0.55,
              animationDuration: bird.duration + 's',
              animationDelay: bird.delay + 's',
            }}
          >
            <svg viewBox="0 0 40 20" className="Birds__svg">
              <path
                className="Birds__wing Birds__wing--left"
                d="M20 12 Q10 4 2 10"
                fill="none"
                stroke="#1A0A20"
                strokeWidth="1.8"
                strokeLinecap="round"
                style={{
                  animationDuration: bird.flapDuration + 's',
                  animationDelay: bird.flapDelay + 's',
                }}
              />
              <path
                className="Birds__wing Birds__wing--right"
                d="M20 12 Q30 4 38 10"
                fill="none"
                stroke="#1A0A20"
                strokeWidth="1.8"
                strokeLinecap="round"
                style={{
                  animationDuration: bird.flapDuration + 's',
                  animationDelay: bird.flapDelay + 's',
                }}
              />
            </svg>
          </div>
        ))}
      </div>
    );
  }
}

export default Birds;
