/** Day-cycle duration in real milliseconds (3 minutes = full day). */
export const DAY_DURATION_MS = 3 * 60 * 1000;

/**
 * Map wall-clock hours to cycle phase t ∈ [0, 1).
 * Midnight → 0, noon → 0.5, etc.
 */
export function clockToPhase(date = new Date()) {
  const ms =
    date.getHours() * 3600000 +
    date.getMinutes() * 60000 +
    date.getSeconds() * 1000 +
    date.getMilliseconds();
  return ms / 86400000;
}

function hexToRgb(hex) {
  const h = hex.replace('#', '');
  const full =
    h.length === 3
      ? h
          .split('')
          .map((c) => c + c)
          .join('')
      : h;
  return {
    r: parseInt(full.slice(0, 2), 16),
    g: parseInt(full.slice(2, 4), 16),
    b: parseInt(full.slice(4, 6), 16),
  };
}

function toHexByte(n) {
  const v = Math.max(0, Math.min(255, Math.round(n)));
  const hex = v.toString(16);
  return hex.length === 1 ? '0' + hex : hex;
}

function rgbToHex({ r, g, b }) {
  return '#' + toHexByte(r) + toHexByte(g) + toHexByte(b);
}

export function lerp(a, b, t) {
  return a + (b - a) * t;
}

export function lerpColor(hexA, hexB, t) {
  const a = hexToRgb(hexA);
  const b = hexToRgb(hexB);
  return rgbToHex({
    r: lerp(a.r, b.r, t),
    g: lerp(a.g, b.g, t),
    b: lerp(a.b, b.b, t),
  });
}

/**
 * Celestial body position on a semicircle arc.
 * elevation: 0 = horizon, 1 = zenith.
 * xPercent: 0–100 left→right.
 */
export function celestialPosition(elevation) {
  // Map elevation [0,1] to angle from east (π) to west (0) via zenith (π/2)
  const angle = Math.PI * (1 - elevation);
  return {
    xPercent: 50 + Math.cos(angle) * 42,
    yPercent: 72 - Math.sin(angle) * 58,
  };
}

