const COLOR_KEYS = [
  'skyTop',
  'skyHorizon',
  'mountainColor',
  'mountainShadow',
  'mountainFade',
  'blimp',
  'cloud',
  'waterTop',
  'waterBottom',
  'forest',
];

const NUMBER_KEYS = [
  'starOpacity',
  'fireflyOpacity',
  'birdOpacity',
  'venusOpacity',
  'sunElevation',
  'moonElevation',
  'sunOpacity',
  'moonOpacity',
];

export function getPalette(t) {
  // Normalize into [0, 1)
  let phase = t % 1;
  if (phase < 0) phase += 1;

  let i = 0;
  while (i < KEYFRAMES.length - 1 && KEYFRAMES[i + 1].t <= phase) {
    i++;
  }

  const a = KEYFRAMES[i];
  const b = KEYFRAMES[Math.min(i + 1, KEYFRAMES.length - 1)];
  const span = b.t - a.t || 1;
  const u = (phase - a.t) / span;

  const out = { t: phase };
  COLOR_KEYS.forEach((key) => {
    out[key] = lerpColor(a[key], b[key], u);
  });
  NUMBER_KEYS.forEach((key) => {
    out[key] = lerp(a[key], b[key], u);
  });

  out.sun = celestialPosition(Math.max(0, out.sunElevation));
  out.moon = celestialPosition(Math.max(0, out.moonElevation));

  return out;
}
