import React, { Component } from 'react';
import PropTypes from 'prop-types';
import MountalGenerator from './generator';
import {getRandomArbitrary, mapPointsToCanvas} from "../utils";
  
const offsetHeight = 0;

class Mountal extends Component {
  static propTypes = {
    levels: PropTypes.number,
    aspectRatio: PropTypes.number,
    rangeId: PropTypes.string,
    index: PropTypes.number
  }

  static defaultProps = {
    levels: 4,
    aspectRatio: 1,
    rangeId: 'r'
  }

  constructor(props) {
    super(props);

    let mountalGenerator = new MountalGenerator(1, props.levels);
    this.points = mountalGenerator.generatePoints([{x: 0, y: 0}, {x: 1, y: 0}]);

    const aspectRatio = props.aspectRatio || 1;
    const canvasWidth = 1000;
    const canvasHeight = canvasWidth * aspectRatio;
    this.canvasWidth = canvasWidth;
    this.canvasHeight = canvasHeight;
    this.polygonPoints =
      `0,${canvasHeight} ` +
      mapPointsToCanvas(this.points, canvasWidth, canvasHeight, offsetHeight) +
      `${canvasWidth},${canvasHeight}`;
    this.shadowPoints = this.buildShadowPolygonPoints(canvasWidth, canvasHeight);
    this.clipId = 'mtn-' + props.rangeId + '-' + props.index;
  }

  shouldComponentUpdate() {
    return false;
  }

  buildShadowPolygonPoints(canvasWidth, canvasHeight) {
    let midPoint = this.points[Math.floor(this.points.length/2)];
    let randomPath = [midPoint];
    let iterations = 20;

    for (var i = 0; i < iterations; i++) {
      let previousPoint = randomPath[i];
      let newPoint = {};
      newPoint.y = previousPoint.y - getRandomArbitrary(1/iterations, 2/iterations);
      newPoint.x = previousPoint.x + getRandomArbitrary(-0.025, 0.05);

      randomPath.push(newPoint);
    }

    let shadowPolygonPoints = mapPointsToCanvas(randomPath, canvasWidth, canvasHeight, offsetHeight);
    shadowPolygonPoints += ` ${canvasWidth},${canvasHeight} ${canvasWidth},0`;
    return shadowPolygonPoints;
  }

  render() {
    return (
      <div style={{position:"relative", zIndex: 0, display: "block", width: "auto", height: "100%", ...this.props.style}}>
        <svg style={{width: "auto", height: "100%"}} viewBox={`0 0 ${this.canvasWidth} ${this.canvasHeight}`}>
          <defs>
          <clipPath id={this.clipId}>
            <polygon points={this.polygonPoints}/>
          </clipPath>
          </defs>

          <polygon className="Mountain__fill" points={this.polygonPoints}/>
          <polygon className="Mountain__shadow" clipPath={"url(#" + this.clipId + ")"} points={this.shadowPoints}/>
          <polygon className="Mountain__fade" style={{opacity:(1 - this.props.z)}} points={this.polygonPoints}/>
        </svg>
      </div>
    );
  }
}

export default Mountal;
