import React, { Component } from 'react';
import MountainRange from './MountainRange';
import Blimp from './Blimp';
import Sky from './Sky';
import Clouds from './Clouds';
import Birds from './Birds';
import Spaceship from './Spaceship';
import {
  DAY_DURATION_MS,
  clockToPhase,
  getPalette,
} from './daycycle/palette';
import './App.css';

// Color CSS vars are expensive (invalidate SVG fills) — keep rare.
const COLOR_MS = 400;

const COLOR_VARS = [
  ['--sky-top', 'skyTop'],
  ['--sky-horizon', 'skyHorizon'],
  ['--mountain-color', 'mountainColor'],
  ['--mountain-shadow', 'mountainShadow'],
  ['--mountain-fade', 'mountainFade'],
  ['--blimp-color', 'blimp'],
  ['--cloud-color', 'cloud'],
];

function applyColorVars(el, palette) {
  if (!el) return;
  const s = el.style;
  for (let i = 0; i < COLOR_VARS.length; i++) {
    s.setProperty(COLOR_VARS[i][0], palette[COLOR_VARS[i][1]]);
  }
  s.setProperty('--star-opacity', String(palette.starOpacity));
  s.setProperty('--bird-opacity', String(palette.birdOpacity));
  s.setProperty('--venus-opacity', String(palette.venusOpacity));
  // 0 by day → 1 at night: stronger UFO light glow in silhouette mode
  s.setProperty('--ship-glow', String(palette.starOpacity));
}

function placeCelestial(el, pos, opacity) {
  if (!el) return;
  // transform only — compositor-friendly, no left/top layout thrash
  el.style.transform =
    'translate3d(' +
    pos.xPercent +
    'vw,' +
    pos.yPercent +
    'vh,0) translate(-50%,-50%)';
  el.style.opacity = opacity > 0.02 ? String(opacity) : '0';
  el.style.visibility = opacity > 0.02 ? 'visible' : 'hidden';
}

class App extends Component {
  constructor(props) {
    super(props);

    this.rootRef = null;
    this.sunEl = null;
    this.moonEl = null;
    this.startWall = performance.now();
    const forced =
      typeof window !== 'undefined'
        ? parseFloat(new URLSearchParams(window.location.search).get('t'))
        : NaN;
    this.startPhase = Number.isFinite(forced)
      ? ((forced % 1) + 1) % 1
      : clockToPhase();
    this.lastColor = 0;
    this.rafId = null;
    this.initialPalette = getPalette(this.startPhase);
  }

  componentDidMount() {
    if (this.rootRef) {
      this.sunEl = this.rootRef.querySelector('.Sky__sun');
      this.moonEl = this.rootRef.querySelector('.Sky__moon');
    }
    applyColorVars(this.rootRef, this.initialPalette);
    placeCelestial(
      this.sunEl,
      this.initialPalette.sun,
      this.initialPalette.sunOpacity
    );
    placeCelestial(
      this.moonEl,
      this.initialPalette.moon,
      this.initialPalette.moonOpacity
    );
    this.tick();
  }

  componentWillUnmount() {
    if (this.rafId != null) {
      cancelAnimationFrame(this.rafId);
    }
  }

  setRootRef = (el) => {
    this.rootRef = el;
  };

  tick = (now) => {
    this.rafId = requestAnimationFrame(this.tick);
    if (now == null) return;

    const elapsed = now - this.startWall;
    const t = (this.startPhase + elapsed / DAY_DURATION_MS) % 1;
    const palette = getPalette(t);

    // Smooth celestial motion every frame
    placeCelestial(this.sunEl, palette.sun, palette.sunOpacity);
    placeCelestial(this.moonEl, palette.moon, palette.moonOpacity);

    // Throttled color updates
    if (now - this.lastColor >= COLOR_MS) {
      this.lastColor = now;
      applyColorVars(this.rootRef, palette);
    }
  };

  render() {
    return (
      <div className="App" ref={this.setRootRef}>
        <Sky />
        <Clouds />
        <Birds />
        <Spaceship />
        <div className="App__blimp">
          <Blimp />
        </div>
        <div className="App__mountains">
          <MountainRange rangeId="a" numberOfMountains={6} />
          <MountainRange rangeId="b" numberOfMountains={6} />
          <MountainRange rangeId="c" numberOfMountains={6} />
        </div>
      </div>
    );
  }
}

export default App;
